from toolz import partition_all
# bad __len__ over-report
class L(list):
    def __len__(self): return super().__len__()+1
try:
    list(partition_all(5, L([1,2]))); print('FAIL: no error (over)')
except LookupError as e: print('OK over:', e)
# bad __len__ under-report
class L2(list):
    def __len__(self): return super().__len__()-1
try:
    list(partition_all(5, L2([1,2]))); print('FAIL: no error (under)')
except LookupError as e: print('OK under:', e)
# correct behavior preserved
print(list(partition_all(2, [1,2,3,4,5])))
print(list(partition_all(3, range(5))))
print(list(partition_all(2, [])))
"

